pm.test("Booking is created and bookingid is stored", function () {
    const responseJson = pm.response.json();

    // Verify booking ID presence and type
    pm.expect(responseJson).to.have.property("bookingid");
    pm.expect(responseJson.bookingid).to.be.a("number");

    // Verify nested booking details match request payload
    pm.expect(responseJson.booking.firstname).to.eql("Jim");
    pm.expect(responseJson.booking.lastname).to.eql("Brown");
